results.body:
flowchart TD
  Loop[getMessageGroups over thread.messages] --> Hidden{isHiddenFromUIMessage}
  Hidden -- yes --> Skip[skip message]
  Hidden -- no --> Type{message.type}
  Type -- human --> Human[human group]
  Type -- tool --> Tool{ask_clarification tool}
  Tool -- yes --> Clarify[clarification group]
  Tool -- no --> Append[append to open group]
  Type -- ai --> Files{hasPresentFiles}
  Files -- yes --> Present[present-files group]
  Files -- no --> Sub{hasSubagent task call}
  Sub -- yes --> Subagent[subagent group]
  Sub -- no --> Proc{hasReasoning or hasToolCalls}
  Proc -- yes --> Processing[processing group]
  Proc -- no --> Asst[assistant bubble]

flowchart TD
  Msg[thread message] --> Hidden{isHiddenFromUIMessage}
  Hidden -- yes --> Skip[skip control msg]
  Hidden -- no --> Type{message.type}
  Type -- human --> GHuman[human group]
  Type -- tool --> Clar{isClarificationToolMessage}
  Type -- ai --> PF{hasPresentFiles}
  Clar -- yes --> GClar[assistant clarification]
  Clar -- no --> Open[append lastOpenGroup]
  PF -- yes --> GPF[assistant present-files]
  PF -- no --> SA{hasSubagent}
  SA -- yes --> GSA[assistant subagent]
  SA -- no --> RT{hasReasoning or hasToolCalls}
  RT -- yes --> GProc[assistant processing merge]

flowchart TD
  Req[get_artifact request] --> Skill{path contains .skill/}
  Skill -->|yes| Extract[_extract_file_from_skill_archive]
  Extract --> SkillDL{download or active mime}
  SkillDL -->|html svg xhtml or download| Attach[attachment FileResponse]
  SkillDL -->|text or other| SkillText[PlainTextResponse]
  Skill -->|no| Resolve[resolve_thread_virtual_path]
  Resolve --> Exists{exists and is_file}
  Exists -->|no| Err[404 or 400 HTTP]
  Exists -->|yes| Download{download flag}
  Download -->|true| Attach
  Download -->|false| Active{mime in ACTIVE_CONTENT_MIME_TYPES}
  Active -->|html xhtml svg| Attach
  Active -->|other| TextCheck{mime starts with text}
  TextCheck -->|yes| Inline[PlainTextResponse inline]
  TextCheck -->|no| BinCheck{is_text_file_by_content}
  BinCheck -->|yes| Inline
  BinCheck -->|no| Binary[inline binary Response]

flowchart TD
  Hook[wrap_tool_call hook] --> Need{_needs_budget?}
  Need -->|no| Keep[return unchanged]
  Need -->|yes| Patch[_patch_tool_message]
  Patch --> Exempt{name in exempt_tools?}
  Exempt -->|yes| Keep
  Exempt -->|no| Ext{over externalize threshold?}
  Ext -->|yes| Sbx{sandbox resolved?}
  Sbx -->|no| Host[_externalize to host outputs_path]
  Sbx -->|yes| Mount{provider uses_thread_data_mounts?}
  Mount -->|yes| Host
  Mount -->|no| SbxFs[_externalize_to_sandbox write_file]
  Host --> Vp{virtual_path ok?}
  SbxFs --> Vp
  Vp -->|yes| Prev[_build_preview head ref tail]
  Vp -->|no| FbChk{over fallback_max_chars?}
  Ext -->|no| FbChk
  FbChk -->|yes| Fb[_build_fallback truncation]
  FbChk -->|no| Keep
  Prev --> Out[model_copy patched ToolMessage]
  Fb --> Out
